#!/usr/bin/env bash
# Regenerate the ABI tables of pkg/sentry/devices/virtgpu from a libdrm checkout.
#
# Usage: gen.sh <libdrm checkout> <output dir>
# The script compiles probe.c with clang for each Linux guest target against
# <libdrm>/include/drm/{drm.h,virtgpu_drm.h} and writes abi_<arch>.txt.
set -euo pipefail

here=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
libdrm=$(cd -- "$1" && pwd)
out=$2
inc="$libdrm/include/drm"
commit=$(git -C "$libdrm" rev-parse HEAD)

for pair in arm64:aarch64-unknown-linux-gnu amd64:x86_64-unknown-linux-gnu; do
	arch=${pair%%:*}
	target=${pair#*:}
	asm=$(clang --target="$target" -nostdinc -isystem "$(clang -print-resource-dir)/include" \
		-I "$here/shim" -I "$inc" -O0 -S -o - "$here/probe.c")
	{
		printf '# Generated by gen.sh. Do not edit.\n'
		printf '# libdrm %s\n' "$commit"
		printf '# sha256 drm.h %s\n' "$(shasum -a 256 "$inc/drm.h" | cut -d' ' -f1)"
		printf '# sha256 virtgpu_drm.h %s\n' "$(shasum -a 256 "$inc/virtgpu_drm.h" | cut -d' ' -f1)"
		printf '# target %s, %s\n' "$target" "$(clang --version | head -n 1)"
		printf '%s\n' "$asm" | awk '
			/^gvx_[a-z]+__.*:$/ { sym = substr($1, 5, length($1) - 5); next }
			sym != "" && ($1 == ".xword" || $1 == ".quad") {
				kind = sym; sub(/__.*/, "", kind)
				name = substr(sym, length(kind) + 3); gsub(/__/, ".", name)
				printf "%s %s %s\n", kind, name, $2
				sym = ""
			}' | LC_ALL=C sort
	} > "$out/abi_$arch.txt"
done
